   val settings=startActivitySync(Intent(c,SettingsActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));photo("03-settings");check(allViews(settings.window.decorView).filterIsInstance<android.widget.Button>().none{it.text.toString() in listOf(settings.getString(R.string.about),settings.getString(R.string.licenses),settings.getString(R.string.privacy))});val legal=allViews(settings.window.decorView).filterIsInstance<android.widget.TextView>().first{it.text.toString()==settings.getString(R.string.legal_information)};runOnMainSync{legal.performClick()};waitForIdleSync();check(accessible(uiAutomation.rootInActiveWindow).any{it.text?.toString()==settings.getString(R.string.licenses)});sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);runOnMainSync{settings.finish()};passed("Legal footer replaces prominent buttons while privacy and full license notices remain accessible")
   for(game in games){val a=startActivitySync(Intent(c,PlayerActivity::class.java).putExtra("id",game.key).putExtra("resume",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500)
    fun surface(v:android.view.View):GameSurface?{if(v is GameSurface)return v;if(v is android.view.ViewGroup)for(i in 0 until v.childCount){val f=surface(v.getChildAt(i));if(f!=null)return f};return null}
    var bitmap:Bitmap?=null;runOnMainSync{bitmap=surface(a.window.decorView)?.snapshot()};check(bitmap!=null){"${game.system}: player displayed no real frame"};bitmap!!.recycle();photo("player-${game.system}");if(game.system=="GBA"){
     runOnMainSync{a.requestedOrientation=android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE};Thread.sleep(1000);var rotated:Bitmap?=null;runOnMainSync{rotated=surface(a.window.decorView)?.snapshot()};check(rotated!=null);rotated!!.recycle();photo("player-GBA-landscape");runOnMainSync{a.requestedOrientation=android.content.pm.ActivityInfo.SCREEN_ORIENTATION_PORTRAIT};Thread.sleep(700)
    };runOnMainSync{a.finish()};val end=System.currentTimeMillis()+4000;while(!a.isDestroyed&&System.currentTimeMillis()<end)Thread.sleep(50);check(a.isDestroyed){"Player did not finish"}};passed("Real player Activity launches and closes for GB/GBC/GBA")
   waitForIdleSync();val cleanupDeadline=android.os.SystemClock.elapsedRealtime()+3000;while(!RomAccess.root(c).listFiles().isNullOrEmpty()&&android.os.SystemClock.elapsedRealtime()<cleanupDeadline)Thread.sleep(50);check(File(c.filesDir,"roms").listFiles().isNullOrEmpty());check(RomAccess.root(c).listFiles().isNullOrEmpty());passed("No retained cartridge cache after sessions")
   runOnMainSync{main.finish()};report.put("status","PASS");out.putString("stream","PASS: ${cases.length()} checks\n")
